import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import { NuqsAdapter } from 'nuqs/adapters/react'

setAdapter(reactAdapter);

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <NuqsAdapter>
  <React.StrictMode>
    <App />
  </React.StrictMode>
  </NuqsAdapter>
);

